[{"id": "nVqQVqTkrWAp2u6hNJKJpoVQey8oV2p7", "function": {"index": 0, "name": "write_file", "arguments": {"path": "config_reader.py", "content": "def read_settings(text):
    lines = text.splitlines()
    seen_keys = set()
    settings = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError("Malformed line: missing '='")
        if stripped.count('=') != 1:
            raise ValueError("Malformed line: more than one '='")
        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()
        if key in seen_keys:
            raise ValueError(f"Duplicate key: {key}")
        seen_keys.add(key)
        if key not in ('endpoint', 'enabled'):
            raise ValueError(f"Unknown key: {key}")
        if key == 'enabled':
            lower = value.lower()
            if lower == 'true':
                enabled_bool = True
            elif lower == 'false':
                enabled_bool = False
            else:
                raise ValueError(f"Invalid value for enabled: {value}")
            settings['enabled'] = enabled_bool
        else:  # endpoint
            settings['endpoint'] = value
    # Verify required keys present
    if 'enabled' not in settings:
        raise ValueError("Missing required key: enabled")
    if 'endpoint' not in settings:
        raise ValueError("Missing required key: endpoint")
    return settings"}}}]
